<?phpsession_start();require_once(__DIR__ . '/../config.php');$pdo = require_once(ROOT . '/source/bdd/connexion_bdd.php');//$pdo = require_once(__DIR__ . '/../source/bdd/connexion_bdd.php');function verifToken(string $token): bool {    return isset($_SESSION['token']) && hash_equals($_SESSION['token'], $token);}$erreurs = [];$valeurs = [    'pseudo' => '',    'email' => '',];if ($_SERVER['REQUEST_METHOD'] !== 'POST') {    header('Location: ../public/inscription.php');    exit;} //fonctionnement plus rigide car si c'est pas en post on par    //au lieu de passer par la verification : if ($_SERVER['REQUEST_METHOD'] === 'POST') {code}    if (!verifToken($_POST['csrf_token'] ?? '')) {        $_SESSION['erreurs'] = ['general' => "Erreur de sécurité. Veuillez réessayer."];        header('Location: ../public/inscription.php');        exit;    }    $pseudo = trim($_POST['pseudo'] ?? '');    $email = trim($_POST['email'] ?? '');    $mdp = $_POST['password'] ?? '';    $passwordConfirm = $_POST['passwordConfirm'] ?? '';    $valeurs = compact('pseudo', 'email');    if (empty($pseudo)) {        $erreurs['pseudo'] = "Veuillez rentrer un pseudo";    } elseif (mb_strlen($pseudo) < 5) {        $erreurs['pseudo'] = "Votre pseudo doit contenir au moins 5 caractères";    } elseif (mb_strlen($pseudo) > 40) {        $erreurs['pseudo'] = "Votre pseudo ne doit pas dépasser 40 caractères";    }    if (empty($email)) {        $erreurs['email'] = "Veuillez rentrer un email";    } elseif (!filter_var($email, FILTER_VALIDATE_EMAIL)) {        $erreurs['email'] = "Format d'email invalide";    } elseif (mb_strlen($email) > 255) {        $erreurs['email'] = "Email trop long";    }    if (empty($mdp)) {        $erreurs['mdp'] = "Veuillez rentrer un mot de passe";    } elseif (mb_strlen($mdp) < 6) {        $erreurs['mdp'] = "Le mot de pase doit contenir au moins 6 caractères";    } else {        // Au moins 1 minuscule, 1 majuscule, 1 chiffre, 1 spécial + longueur mini 6        $regex = '/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[!@#$%^&*()_\-+=\[\]{};:\'",.<>\/?\\|`~]).{6,}$/';        if (!preg_match($regex, $mdp)) {            $erreurs['mdp'] = "Le mot de passe doit contenir au moins une majuscule, une minuscule, un chiffre et un caractère spécial";        }    }    if (empty($passwordConfirm)) {        $erreurs['passwordConfirm'] = "Veuillez confirmer le mot de passe";    } elseif ($mdp !== $passwordConfirm) {        $erreurs['passwordConfirm'] = "Les mots de passe ne correspondent pas";    }    if (empty($erreurs)) {        try {            $verif = $pdo->prepare(" SELECT pseudo, email FROM utilisateur WHERE pseudo = :pseudo OR email = :email LIMIT 1");            $verif->execute([                ':pseudo' => $pseudo,                ':email' => $email            ]);            $utilisateurExistant = $verif->fetch(PDO::FETCH_ASSOC);            if ($utilisateurExistant) {                if ($utilisateurExistant['pseudo'] === $pseudo) {                    $erreurs['pseudo'] = "Ce pseudo est déjà utilisé.";                }                if ($utilisateurExistant['email'] === $email) {                    $erreurs['email'] = "Cette adresse e-mail est déjà utilisée.";                }            } else {                $mdpHash = password_hash($mdp, PASSWORD_DEFAULT);                $requete = $pdo->prepare(                    "INSERT INTO utilisateur(pseudo, email, mdp) VALUES (:pseudo, :email, :mdp) ");                $requete->execute([                    "pseudo" => $pseudo,                    "email" => $email,                    "mdp" => $mdpHash                ]);                $_SESSION['succes'] = "Votre compte a été créé !";                $_SESSION['valeurs'] = ['pseudo' => '', 'email' => ''];                unset($_SESSION['token']); //regener le token si pas d'erreurs                header('Location: ../public/inscription.php');                exit;            }        }catch (PDOException $e) {            // Afficher les erreurs            error_log("Erreur inscription : " . $e->getMessage());            $erreurs['general'] = "Erreur lors de l'inscription. Veuillez réessayer.";        }    }    $_SESSION['erreurs'] = $erreurs;    $_SESSION['valeurs'] = $valeurs;    header('Location: ' . BASE_URL . '/public/inscription.php');//systeme de confimation d'email ?    exit;